-- PostgreSQL 16+. Tenant relationships include workspace_id in every foreign key.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE "user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "session" (id text PRIMARY KEY, "expiresAt" timestamptz NOT NULL, token text NOT NULL UNIQUE, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE INDEX session_user_idx ON "session"("userId");
CREATE TABLE account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), UNIQUE("providerId","accountId"));
CREATE TABLE verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX verification_identifier_idx ON verification(identifier);
CREATE TABLE workspace (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, owner_id text NOT NULL REFERENCES "user"(id),
 business_email text NOT NULL, business_address text NOT NULL DEFAULT '', timezone text NOT NULL DEFAULT 'America/Chicago', week_start integer NOT NULL DEFAULT 1 CHECK(week_start BETWEEN 0 AND 6),
 currency text NOT NULL DEFAULT 'USD' CHECK(currency='USD'), default_rate integer NOT NULL DEFAULT 15000 CHECK(default_rate>=0), cost_rate integer CHECK(cost_rate>=0), target_rate integer CHECK(target_rate>=0), capacity_seconds integer CHECK(capacity_seconds>0),
 payment_terms integer NOT NULL DEFAULT 14 CHECK(payment_terms BETWEEN 0 AND 365), rounding_minutes integer NOT NULL DEFAULT 0 CHECK(rounding_minutes IN (0,1,5,6,10,15,30)), ai_enabled boolean NOT NULL DEFAULT false, demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id)
);
CREATE TABLE membership (workspace_id uuid PRIMARY KEY REFERENCES workspace(id), user_id text NOT NULL REFERENCES "user"(id), role text NOT NULL DEFAULT 'owner' CHECK(role='owner'), UNIQUE(workspace_id,user_id));
CREATE TABLE device_credential (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspace(id), user_id text NOT NULL REFERENCES "user"(id), name text NOT NULL, token_hash text NOT NULL UNIQUE, scopes text[] NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), verified_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, revoked_at timestamptz, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,user_id) REFERENCES membership(workspace_id,user_id));
CREATE TABLE client (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspace(id), name text NOT NULL, email text NOT NULL, address text NOT NULL DEFAULT '', color text NOT NULL DEFAULT '#a3afa5', default_rate integer CHECK(default_rate>=0), payment_terms integer CHECK(payment_terms BETWEEN 0 AND 365), archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id));
CREATE TABLE client_contact (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, client_id uuid NOT NULL, name text NOT NULL, email text NOT NULL, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,client_id) REFERENCES client(workspace_id,id));
CREATE TABLE project (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, client_id uuid NOT NULL, name text NOT NULL, description text NOT NULL DEFAULT '', color text NOT NULL DEFAULT '#b8ad84', model text NOT NULL CHECK(model IN ('hourly','fixed','prepaid','support')), rate integer CHECK(rate>=0), fee integer NOT NULL DEFAULT 0 CHECK(fee>=0), budget integer CHECK(budget>=0), estimate_seconds integer CHECK(estimate_seconds>0), cost_rate integer CHECK(cost_rate>=0), target_rate integer CHECK(target_rate>=0), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','completed','archived')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), UNIQUE(workspace_id,client_id,id), FOREIGN KEY(workspace_id,client_id) REFERENCES client(workspace_id,id));
CREATE TABLE billing_terms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, project_id uuid NOT NULL, version integer NOT NULL, snapshot jsonb NOT NULL, effective_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), UNIQUE(project_id,version), FOREIGN KEY(workspace_id,project_id) REFERENCES project(workspace_id,id));
CREATE TABLE project_task (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, project_id uuid NOT NULL, title text NOT NULL, completed_at timestamptz, UNIQUE(workspace_id,id), UNIQUE(workspace_id,project_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES project(workspace_id,id));
CREATE TABLE timer_session (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, user_id text NOT NULL, project_id uuid NOT NULL, task_id uuid, description text NOT NULL DEFAULT '', billable boolean NOT NULL DEFAULT true, state text NOT NULL CHECK(state IN ('running','paused','stopped')), started_at timestamptz NOT NULL, segment_started_at timestamptz, accumulated_seconds integer NOT NULL DEFAULT 0 CHECK(accumulated_seconds>=0), rate integer NOT NULL CHECK(rate>=0), rounding_minutes integer NOT NULL DEFAULT 0, version integer NOT NULL DEFAULT 1, stopped_at timestamptz, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,user_id) REFERENCES membership(workspace_id,user_id), FOREIGN KEY(workspace_id,project_id) REFERENCES project(workspace_id,id), FOREIGN KEY(workspace_id,project_id,task_id) REFERENCES project_task(workspace_id,project_id,id));
CREATE UNIQUE INDEX one_active_timer_per_user ON timer_session(user_id) WHERE state IN ('running','paused');
CREATE TABLE time_entry (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, user_id text NOT NULL, project_id uuid NOT NULL, task_id uuid, timer_id uuid, description text NOT NULL DEFAULT '', private_note text NOT NULL DEFAULT '', started_at timestamptz NOT NULL, ended_at timestamptz NOT NULL, actual_seconds integer NOT NULL CHECK(actual_seconds>0), billed_seconds integer NOT NULL CHECK(billed_seconds>=0), rate integer NOT NULL CHECK(rate>=0), currency text NOT NULL DEFAULT 'USD' CHECK(currency='USD'), billable boolean NOT NULL, treatment text NOT NULL CHECK(treatment IN ('hourly','fixed','prepaid','support','nonbillable','overage','written_off')), covered_seconds integer NOT NULL DEFAULT 0 CHECK(covered_seconds>=0 AND covered_seconds<=actual_seconds), reviewed boolean NOT NULL DEFAULT false, rounding_minutes integer NOT NULL DEFAULT 0, version integer NOT NULL DEFAULT 1, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), CHECK(ended_at>started_at), FOREIGN KEY(workspace_id,user_id) REFERENCES membership(workspace_id,user_id), FOREIGN KEY(workspace_id,project_id) REFERENCES project(workspace_id,id), FOREIGN KEY(workspace_id,project_id,task_id) REFERENCES project_task(workspace_id,project_id,id), FOREIGN KEY(workspace_id,timer_id) REFERENCES timer_session(workspace_id,id));
CREATE INDEX time_period_idx ON time_entry(workspace_id,started_at) WHERE deleted_at IS NULL;
CREATE TABLE billing_agreement (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, project_id uuid NOT NULL, fee integer NOT NULL CHECK(fee>0), currency text NOT NULL DEFAULT 'USD' CHECK(currency='USD'), frequency text NOT NULL CHECK(frequency IN ('weekly','monthly')), anchor date NOT NULL, timezone text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','paused','cancelled')), end_date date, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES project(workspace_id,id));
CREATE TABLE billing_period (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, agreement_id uuid NOT NULL, starts_on date NOT NULL, ends_on date NOT NULL, fee integer NOT NULL CHECK(fee>0), UNIQUE(workspace_id,id), UNIQUE(agreement_id,starts_on), CHECK(ends_on>starts_on), FOREIGN KEY(workspace_id,agreement_id) REFERENCES billing_agreement(workspace_id,id));
CREATE TABLE fixed_milestone (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, project_id uuid NOT NULL, title text NOT NULL, amount integer NOT NULL CHECK(amount>0), ready boolean NOT NULL DEFAULT false, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES project(workspace_id,id));
CREATE TABLE retainer_bucket (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, project_id uuid NOT NULL, name text NOT NULL, purchased_seconds integer NOT NULL CHECK(purchased_seconds>0), price integer NOT NULL CHECK(price>0), currency text NOT NULL DEFAULT 'USD' CHECK(currency='USD'), activated_at timestamptz, expires_at timestamptz, overage_policy text NOT NULL DEFAULT 'review' CHECK(overage_policy='review'), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES project(workspace_id,id));
CREATE TABLE invoice (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, client_id uuid NOT NULL, number text NOT NULL, currency text NOT NULL DEFAULT 'USD' CHECK(currency='USD'), revision integer NOT NULL DEFAULT 1, approval_state text NOT NULL DEFAULT 'draft' CHECK(approval_state IN ('draft','review','approved')), issuance_state text NOT NULL DEFAULT 'local' CHECK(issuance_state IN ('local','queued','issued','void')), collection_state text NOT NULL DEFAULT 'unpaid' CHECK(collection_state IN ('unpaid','processing','paid','failed','authentication_required','partial','refunded','disputed')), subtotal integer NOT NULL DEFAULT 0 CHECK(subtotal>=0), discount integer NOT NULL DEFAULT 0 CHECK(discount>=0), tax_bps integer NOT NULL DEFAULT 0 CHECK(tax_bps BETWEEN 0 AND 10000), tax integer NOT NULL DEFAULT 0 CHECK(tax>=0), total integer NOT NULL DEFAULT 0 CHECK(total>=0), paid_amount integer NOT NULL DEFAULT 0 CHECK(paid_amount>=0), memo text NOT NULL DEFAULT '', po_reference text NOT NULL DEFAULT '', business_snapshot jsonb NOT NULL, client_snapshot jsonb NOT NULL, due_at timestamptz NOT NULL, issued_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), provider text NOT NULL DEFAULT 'demo' CHECK(provider IN ('demo','stripe_test')), provider_account text, provider_invoice text, provider_url text, provider_pdf text, provider_verified_at timestamptz, UNIQUE(workspace_id,id), UNIQUE(workspace_id,number), UNIQUE(provider,provider_account,provider_invoice), CHECK(total=subtotal-discount+tax), CHECK(discount<=subtotal), FOREIGN KEY(workspace_id,client_id) REFERENCES client(workspace_id,id));
CREATE TABLE invoice_line (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, invoice_id uuid NOT NULL, project_id uuid NOT NULL, description text NOT NULL, quantity_seconds integer NOT NULL DEFAULT 0, unit_rate integer NOT NULL DEFAULT 0, amount integer NOT NULL CHECK(amount>=0), source_kind text NOT NULL CHECK(source_kind IN ('time','milestone','period','bucket')), service_start timestamptz, service_end timestamptz, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,invoice_id) REFERENCES invoice(workspace_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES project(workspace_id,id));
CREATE TABLE invoice_source_allocation (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, invoice_id uuid NOT NULL, line_id uuid NOT NULL, time_entry_id uuid, milestone_id uuid, period_id uuid, bucket_id uuid, released_at timestamptz, UNIQUE(workspace_id,id), CHECK(num_nonnulls(time_entry_id,milestone_id,period_id,bucket_id)=1), FOREIGN KEY(workspace_id,invoice_id) REFERENCES invoice(workspace_id,id), FOREIGN KEY(workspace_id,line_id) REFERENCES invoice_line(workspace_id,id), FOREIGN KEY(workspace_id,time_entry_id) REFERENCES time_entry(workspace_id,id), FOREIGN KEY(workspace_id,milestone_id) REFERENCES fixed_milestone(workspace_id,id), FOREIGN KEY(workspace_id,period_id) REFERENCES billing_period(workspace_id,id), FOREIGN KEY(workspace_id,bucket_id) REFERENCES retainer_bucket(workspace_id,id));
CREATE UNIQUE INDEX allocated_time_once ON invoice_source_allocation(time_entry_id) WHERE released_at IS NULL;
CREATE UNIQUE INDEX allocated_milestone_once ON invoice_source_allocation(milestone_id) WHERE released_at IS NULL;
CREATE UNIQUE INDEX allocated_period_once ON invoice_source_allocation(period_id) WHERE released_at IS NULL;
CREATE UNIQUE INDEX allocated_bucket_once ON invoice_source_allocation(bucket_id) WHERE released_at IS NULL;
CREATE TABLE invoice_revision (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, invoice_id uuid NOT NULL, revision integer NOT NULL, snapshot jsonb NOT NULL, hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), UNIQUE(invoice_id,revision), FOREIGN KEY(workspace_id,invoice_id) REFERENCES invoice(workspace_id,id));
CREATE TABLE connected_payment_account (workspace_id uuid PRIMARY KEY REFERENCES workspace(id), provider text NOT NULL CHECK(provider IN ('demo','stripe_test')), account_id text NOT NULL, ready boolean NOT NULL DEFAULT false, details jsonb NOT NULL DEFAULT '{}', disconnected_at timestamptz, UNIQUE(provider,account_id));
CREATE TABLE client_payment_profile (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, client_id uuid NOT NULL, provider text NOT NULL CHECK(provider IN ('demo','stripe_test')), account_id text NOT NULL, customer_id text NOT NULL, payment_method_id text, card_suffix text, UNIQUE(workspace_id,id), UNIQUE(workspace_id,client_id,provider,account_id), UNIQUE(provider,account_id,customer_id), FOREIGN KEY(workspace_id,client_id) REFERENCES client(workspace_id,id));
CREATE TABLE auto_charge_consent (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, client_id uuid NOT NULL, profile_id uuid NOT NULL, terms_version text NOT NULL, frequency text NOT NULL, amount_policy text NOT NULL, accepted_at timestamptz NOT NULL, revoked_at timestamptz, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,client_id) REFERENCES client(workspace_id,id), FOREIGN KEY(workspace_id,profile_id) REFERENCES client_payment_profile(workspace_id,id));
CREATE TABLE invoice_approval (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, invoice_id uuid NOT NULL, revision integer NOT NULL, snapshot_hash text NOT NULL, action text NOT NULL CHECK(action IN ('send','charge')), payment_method_id text, consent_id uuid, actor_id text NOT NULL, approved_at timestamptz NOT NULL DEFAULT now(), invalidated_at timestamptz, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,invoice_id) REFERENCES invoice(workspace_id,id), FOREIGN KEY(workspace_id,consent_id) REFERENCES auto_charge_consent(workspace_id,id));
CREATE TABLE payment_operation (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, invoice_id uuid NOT NULL, approval_id uuid NOT NULL UNIQUE, action text NOT NULL CHECK(action IN ('send','charge')), state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','processing','reconcile','succeeded','failed','blocked')), idempotency_key text NOT NULL UNIQUE, provider_invoice text, error_code text, attempts integer NOT NULL DEFAULT 0, locked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,invoice_id) REFERENCES invoice(workspace_id,id), FOREIGN KEY(workspace_id,approval_id) REFERENCES invoice_approval(workspace_id,id));
CREATE UNIQUE INDEX one_pending_invoice_operation ON payment_operation(invoice_id) WHERE state IN ('queued','processing','reconcile');
CREATE TABLE payment (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, invoice_id uuid NOT NULL, operation_id uuid, provider text NOT NULL CHECK(provider IN ('demo','stripe_test','external')), account_id text NOT NULL, provider_payment text NOT NULL, amount integer NOT NULL CHECK(amount>0), currency text NOT NULL DEFAULT 'USD' CHECK(currency='USD'), service_amount integer NOT NULL CHECK(service_amount>=0 AND service_amount<=amount), fee integer CHECK(fee>=0), received_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), UNIQUE(provider,account_id,provider_payment), FOREIGN KEY(workspace_id,invoice_id) REFERENCES invoice(workspace_id,id), FOREIGN KEY(workspace_id,operation_id) REFERENCES payment_operation(workspace_id,id));
CREATE TABLE payment_adjustment (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, payment_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('refund','credit','dispute')), amount integer NOT NULL CHECK(amount>0), provider_ref text NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), UNIQUE(payment_id,provider_ref), FOREIGN KEY(workspace_id,payment_id) REFERENCES payment(workspace_id,id));
CREATE TABLE retainer_ledger_entry (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, bucket_id uuid NOT NULL, time_entry_id uuid, payment_id uuid, reverses_id uuid, kind text NOT NULL CHECK(kind IN ('grant','consume','reverse','expire','adjust')), seconds integer NOT NULL CHECK(seconds<>0), source_key text NOT NULL UNIQUE, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), CHECK((kind IN ('grant','reverse') AND seconds>0) OR (kind IN ('consume','expire') AND seconds<0) OR kind='adjust'), FOREIGN KEY(workspace_id,bucket_id) REFERENCES retainer_bucket(workspace_id,id), FOREIGN KEY(workspace_id,time_entry_id) REFERENCES time_entry(workspace_id,id), FOREIGN KEY(workspace_id,payment_id) REFERENCES payment(workspace_id,id), FOREIGN KEY(workspace_id,reverses_id) REFERENCES retainer_ledger_entry(workspace_id,id));
CREATE UNIQUE INDEX retainer_grant_once ON retainer_ledger_entry(bucket_id) WHERE kind='grant';
CREATE UNIQUE INDEX retainer_reversal_once ON retainer_ledger_entry(reverses_id) WHERE reverses_id IS NOT NULL;
CREATE TABLE repository_mapping (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, project_id uuid NOT NULL, identity text NOT NULL, alias text NOT NULL DEFAULT '', UNIQUE(workspace_id,id), UNIQUE(workspace_id,identity), FOREIGN KEY(workspace_id,project_id) REFERENCES project(workspace_id,id));
CREATE TABLE activity_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, repository_id uuid NOT NULL, commit_ref text NOT NULL, subject text, branch text, occurred_at timestamptz NOT NULL, UNIQUE(workspace_id,id), UNIQUE(workspace_id,repository_id,commit_ref), FOREIGN KEY(workspace_id,repository_id) REFERENCES repository_mapping(workspace_id,id));
CREATE TABLE activity_suggestion (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, evidence_id uuid NOT NULL, project_id uuid NOT NULL, reason text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected')), time_entry_id uuid, UNIQUE(workspace_id,id), UNIQUE(evidence_id), FOREIGN KEY(workspace_id,evidence_id) REFERENCES activity_evidence(workspace_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES project(workspace_id,id), FOREIGN KEY(workspace_id,time_entry_id) REFERENCES time_entry(workspace_id,id));
CREATE TABLE notification (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspace(id), dedup_key text NOT NULL, title text NOT NULL, detail text NOT NULL, target text NOT NULL, kind text NOT NULL, snoozed_until timestamptz, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), UNIQUE(workspace_id,dedup_key));
CREATE TABLE audit_event (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspace(id), actor_id text NOT NULL, action text NOT NULL, record_id text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id));
CREATE TABLE webhook_inbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspace(id), provider text NOT NULL CHECK(provider='stripe_test'), account_id text NOT NULL, event_id text NOT NULL, event_type text NOT NULL, object_id text NOT NULL, state text NOT NULL DEFAULT 'pending', received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, error_code text, UNIQUE(provider,account_id,event_id));
CREATE TABLE client_access (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, client_id uuid NOT NULL, invoice_id uuid NOT NULL, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,client_id) REFERENCES client(workspace_id,id), FOREIGN KEY(workspace_id,invoice_id) REFERENCES invoice(workspace_id,id));
CREATE TABLE close_review (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspace(id), starts_on date NOT NULL, ends_on date NOT NULL, step integer NOT NULL DEFAULT 0 CHECK(step BETWEEN 0 AND 4), notes text NOT NULL DEFAULT '', completed_at timestamptz, UNIQUE(workspace_id,id), UNIQUE(workspace_id,starts_on,ends_on));
CREATE TABLE ai_draft_provenance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspace(id), invoice_id uuid, provider text NOT NULL, model text, source_ids uuid[] NOT NULL, warnings text[] NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,invoice_id) REFERENCES invoice(workspace_id,id));
CREATE TABLE idempotency_record (workspace_id uuid NOT NULL REFERENCES workspace(id), key text NOT NULL, action text NOT NULL, request_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,key));
CREATE TABLE rate_limit (key text PRIMARY KEY, window_at timestamptz NOT NULL, count integer NOT NULL);
-- Ledger/revision/audit history is append-only even if a service has a bug.
CREATE FUNCTION deny_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'History is append-only'; END $$;
CREATE TRIGGER ledger_immutable BEFORE UPDATE OR DELETE ON retainer_ledger_entry FOR EACH ROW EXECUTE FUNCTION deny_history_mutation();
CREATE TRIGGER revisions_immutable BEFORE UPDATE OR DELETE ON invoice_revision FOR EACH ROW EXECUTE FUNCTION deny_history_mutation();
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_event FOR EACH ROW EXECUTE FUNCTION deny_history_mutation();
CREATE FUNCTION guard_billed_entry() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM invoice_source_allocation a WHERE a.time_entry_id=OLD.id AND a.released_at IS NULL) THEN RAISE EXCEPTION 'Allocated time is locked; remove it from the draft or issue an adjustment'; END IF; RETURN NEW;
END $$;
CREATE TRIGGER billed_time_locked BEFORE UPDATE OR DELETE ON time_entry FOR EACH ROW EXECUTE FUNCTION guard_billed_entry();
